<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { fetchOrders, orderStatusNames } from '../../api/workorder'
import { useBusinessRead } from '../../composables/useBusinessRead'
import type { OrderQuery } from '../../api/workorder'
import { useAuthStore } from '../../stores/auth'
const auth = useAuthStore(), keywordLabel = computed(() => auth.currentUser?.role === 'ADMIN' ? '搜索编号／原设备名／维修人员' : '搜索编号／原设备名')
const route = useRoute(), router = useRouter(), keyword = shallowRef(String(route.query.keyword ?? '')), status = shallowRef(String(route.query.status ?? '')), scope = shallowRef(String(route.query.scope ?? (route.path === '/tasks' ? 'CURRENT' : 'ALL')))
const { data, loading, message, stale, lastSuccessAt, clear, load } = useBusinessRead(() => fetchOrders({ page: Math.max(1, Number(route.query.page ?? 1) || 1), pageSize: 20, keyword: String(route.query.keyword ?? ''), status: String(route.query.status ?? ''), scope: String(route.query.scope ?? (route.path === '/tasks' ? 'CURRENT' : 'ALL')) as OrderQuery['scope'] }))
function apply(page = 1) { void router.replace({ path: route.path, query: { keyword: keyword.value, status: status.value, scope: scope.value, page: String(page) } }) }
watch(() => route.fullPath, () => { clear(); void load() }, { immediate: true })
</script>
<template><div class="page-heading"><h1>{{ route.path === '/tasks' ? '我的任务与历史' : route.path.startsWith('/admin') ? '工单管理' : '我的工单' }}</h1></div><section class="card"><form @submit.prevent="apply()"><div class="form-grid"><label>查询范围<select v-model="scope"><option value="ALL">全部本人可见</option><option value="CURRENT">当前未完结</option><option value="HISTORY">完结／本人分派历史</option></select></label><label>工单状态<select v-model="status"><option value="">全部状态</option><option v-for="(name, code) in orderStatusNames" :key="code" :value="code">{{ name }}</option></select></label><label>{{ keywordLabel }}<input v-model="keyword" maxlength="100"></label></div><div class="actions"><button class="primary" :disabled="loading">应用筛选</button><button type="button" class="secondary" :disabled="loading" @click="load">刷新</button></div></form><p v-if="loading" role="status">正在读取工单…</p><p v-if="message" class="notice" role="alert">{{ message }} {{ stale ? `上次成功 ${lastSuccessAt}，资料可能过期。` : '' }}</p><p v-if="data && !data.records.length" class="muted">此范围暂无可见工单。</p><ul v-if="data" class="business-list"><li v-for="o in data.records" :key="o.id"><RouterLink :to="{ path: `/work-orders/${o.id}`, query: { returnTo: route.fullPath } }"><strong>{{ o.workOrderNo }}</strong><span>{{ o.reportedEquipmentName }} · {{ o.isRework ? '返工处理中' : orderStatusNames[o.status] }}</span><small>{{ o.locationNameSnapshot ?? '旧文字位置' }} · {{ o.equipment ? `台账 ${o.equipment.equipmentNo}` : '未关联台账' }} · {{ o.historyScope === 'ASSIGNMENT_ONLY' ? '本人分派历史' : '业务材料' }}</small></RouterLink></li></ul><div v-if="data" class="actions"><span>共{{ data.total }}条</span><button class="secondary" :disabled="loading || data.page <= 1" @click="apply(data.page - 1)">上一页</button><span>第{{ data.page }}页</span><button class="secondary" :disabled="loading || data.page * data.pageSize >= data.total" @click="apply(data.page + 1)">下一页</button></div></section></template>

